alter table ouf_udp.materialization_job add column missing_ref_hashes jsonb default '["sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"]';
